	/*
     * @param	event CreateOperationEvent
     */
    @EventHandler( payloadType=CreateOperationEvent.class )
    public void handle( CreateOperationEvent event) {
	    LOGGER.info("handling CreateOperationEvent - " + event );
	    Operation entity = new Operation();
            entity.setOperationId( event.getOperationId() );
            entity.setOperationNumber( event.getOperationNumber() );
            entity.setName( event.getName() );
            entity.setSetupTime( event.getSetupTime() );
            entity.setStandardCycleTime( event.getStandardCycleTime() );
            entity.setOperationType( event.getOperationType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllOperation( entity );
    }

    /*
     * @param	event UpdateOperationEvent
     */
    @EventHandler( payloadType=UpdateOperationEvent.class )
    public void handle( UpdateOperationEvent event) {
    	LOGGER.info("handling UpdateOperationEvent - " + event );
    	
	    Operation entity = new Operation();
            entity.setOperationId( event.getOperationId() );
            entity.setOperationNumber( event.getOperationNumber() );
            entity.setName( event.getName() );
            entity.setSetupTime( event.getSetupTime() );
            entity.setStandardCycleTime( event.getStandardCycleTime() );
            entity.setRouting( event.getRouting() );
            entity.setWorkCenter( event.getWorkCenter() );
            entity.setInspectionPlan( event.getInspectionPlan() );
            entity.setOperationType( event.getOperationType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindOperation( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllOperation( entity );        
    }
    
