    /**
     * Method to retrieve the Operation via an OperationPrimaryKey.
     * @param 	id Long
     * @return 	Operation
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Operation handle( FindOperationQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getOperationId() );
    }
    
    /**
     * Method to retrieve a collection of all Operations
     *
     * @param	query	FindAllOperationQuery 
     * @return 	List<Operation> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Operation> handle( FindAllOperationQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindOperation,
 * but only if the id matches
 *
 * @param		entity	Operation
 */
	protected void emitFindOperation( Operation entity ) {
		LOGGER.info("handling emitFindOperation" );
		
	    queryUpdateEmitter.emit(FindOperationQuery.class,
	                            query -> query.getFilter().getOperationId().equals(entity.getOperationId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllOperation
	 * 
	 * @param		entity	Operation
	 */
	protected void emitFindAllOperation( Operation entity ) {
		LOGGER.info("handling emitFindAllOperation" );
		
	    queryUpdateEmitter.emit(FindAllOperationQuery.class,
	                            query -> true,
	                            entity);
	}

